// Immutable sibling objects generated by Growth. Originals stay in product data/details.
export function productCardImage(src:string):string {
 try {
  const u=new URL(src);
  if(u.origin!=='https://qzvpayjaadbmpayeglon.supabase.co'||u.search||!/^\/storage\/v1\/object\/public\/(products|images)\/.+\.(jpe?g|png|webp)$/i.test(u.pathname))return src;
  u.pathname += '.card-320.webp';
  return u.href;
 }catch{return src;}
}
